pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up a specific scenario: block.timestamp and block.difficulty are both even, 
        // and msg.sender is chosen so that keccak256(abi.encodePacked(...)) % 2 == 0.
        // We use vm.warp and vm.roll to control block.timestamp and block.difficulty.
        vm.warp(2); // even timestamp
        vm.roll(2); // even difficulty
        address alice = address(0x1234);
        vm.deal(alice, 10 ether);
        vm.prank(alice);
        c.play{value: 10}();
        // In reference: random == 0 => pot becomes 0.
        // In bug: random != 0 => pot stays 10 (since condition fails).
        assertTrue(c.pot() == 0);
    }
}

