pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Arrange: set Alice and Bob
        address alice = address(0x1111);
        address bob = address(0x2222);
        vm.deal(alice, 10 ether);
        vm.deal(bob, 10 ether);

        // Act: Alice plays first
        vm.prank(alice);
        c.play{value: 10}();

        // Record the pot after Alice's call
        uint potAfterAlice = c.pot();

        // Act: Bob plays
        vm.prank(bob);
        c.play{value: 10}();

        // Record pot after Bob's call
        uint potAfterBob = c.pot();

        // Assert: In the reference (random == 0), Alice's call resets pot to 0, then Bob's call adds 10 and (if random == 0 for Bob) resets to 0 again, so potAfterAlice == 0. In the bug (random != 0), Alice's call does nothing to pot (remains 10), then Bob's call adds 10 and (if random != 0 for Bob) pays out, resetting to 0. So we can assert that potAfterAlice is 0 in the reference but 10 in the bug.
        // Because random is unpredictable but deterministic (depends on block.timestamp, block.difficulty, sender), we rely on the concrete values at test execution time. The point is that the *behavior* differs: for the *same* block parameters, the reference and mutant diverge on which player gets the payout. Here we simply check potAfterAlice == 0, knowing that in the reference this holds (since when random==0, pot resets) and in the mutant it may be 10 (since when random!=0, pot does not reset).
        // To guarantee this test passes on reference and fails on mutant, we need a deterministic scenario: we can control block.timestamp and block.difficulty.
        // Actually, we can set block.timestamp and block.difficulty to ensure a known random outcome.
        // Let's redo with known values that force random == 0 for Alice's call in the reference.
    }
}

