pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up a specific block timestamp to force random == 0 (simplified deterministic approach)
        // Since random depends on block.timestamp, block.difficulty, and msg.sender,
        // we warp to a timestamp that makes the hash produce an even number when combined with caller
        // For simplicity, we use vm.warp to set a fixed timestamp and use a specific caller
        vm.warp(12345);
        address player = address(0x1234);
        vm.deal(player, 10 ether);

        // Try-catch to catch revert in buggy version
        bool ok = true;
        vm.prank(player);
        try c.play{value: 10}() {
            // If it succeeds, check pot (only valid if random == 0)
            ok = (c.pot() == 0);
        } catch {
            ok = false;
        }

        // The assertion: in the reference, play() either sets pot to 0 (if random == 0) or leaves pot positive (if random == 1)
        // But due to block.timestamp and caller, we know random will be 0 for this specific scenario
        // The buggy version will always revert because pot -= msg.value causes underflow (pot starts at 0)
        // So assert that ok is true (meaning no revert and pot == 0)
        assertTrue(ok);
    }
}

