pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund the caller with enough Ether
        vm.deal(address(this), 10 ether);
        // Call play() – msg.value = 10, and assume we are unlucky (random != 0)
        // Since random is deterministic: block.timestamp (0), block.difficulty (0), msg.sender (this)
        // keccak256(abi.encodePacked(0, 0, this)) % 2 is something, likely 0 or 1.
        // To guarantee random != 0 we can use a simple trick: we just call once and observe.
        // If random == 0 this test might fail; but we want a concrete witness.
        // We'll instead control by using a different caller whose address makes random != 0.
        // Let's pick a caller address where the hash modulo 2 is 1.
        // We can brute-force mentally: address(0x...01) will have least significant byte 1 but hash isn't linear. 
        // Simpler: we call and if random == 0 the test would pass on bug too? No, we need divergence.
        // Better: we call play() with a known sender that gives random == 1 for these block values.
        // Hard-code: address 0x0000000000000000000000000000000000000001, with block.timestamp=0, block.difficulty=0.
        address caller = address(0x1);
        vm.deal(caller, 10 ether);
        vm.prank(caller);
        c.play{value: 10}();
        // After play(), if random != 0, pot stays unchanged in reference (=10) but bug subtracts 10 making pot = -10 (underflow)
        // However, underflow in Solidity 0.8+ reverts on subtraction? Actually, unchecked? pot is uint, subtraction reverts on underflow.
        // So bug would revert before reaching pot check. Thus the call itself reverts for bug, succeeds for reference.
        // So we can wrap in try/catch.
        bool ok;
        try this.dummy() { ok = true; } catch { ok = false; } // dummy, we need to re-call
        // Actually we already called, the revert would have made tx fail. Use try/catch on the invocation.
        // Let's do a fresh call on a new contract? No, we need same contract. 
        // We'll recreate: set up again with fresh contract, do try/catch.
        // Simpler: redo inside a try/catch block.
    }
}

