import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Call play with value 10, ensure random != 0 by choosing a sender that makes hash even (0) or odd (1).
        // We'll try multiple callers until random != 0.
        address player1 = address(0x1);
        address player2 = address(0x2);
        vm.deal(player1, 10);
        vm.prank(player1);
        c.play{value: 10}();
        vm.deal(player2, 10);
