        // The first call with player1: block.timestamp and block.difficulty are default (1, 0), to get odd result we need (1*0*0x1)%2 = 1 -> odd -> lose.
        // So pot is 10 in reference, underflow in bug.
        assertTrue(c.pot() == 10);
    }
}

