pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set block.timestamp and block.difficulty to force random == 0 (win)
        vm.warp(1);
        vm.roll(1);
        vm.deal(address(0x1), 10);
        vm.prank(address(0x1));
        // Call play() with 10 wei; will win because keccak256(abi.encodePacked(1, 1, 0x1)) % 2 == 0
        c.play{value: 10}();
        // After win: reference sends player 9 wei (pot 10 - 1 fee), buggy sends 0 wei (pot 0 - 1 underflow but SafeMath not used, so sends 0)
        // Check player's balance: reference gives 9, bug gives 0
        assertTrue(address(0x1).balance == 9);
    }
}

