pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set block.timestamp and difficulty to ensure random == 0
        vm.warp(1);
        vm.roll(1);
        // Use a specific sender so random is 0
        address player = address(0x1234);
        vm.deal(player, 10);
        vm.prank(player);
        // attempt to play
        bool ok;
        try c.play{value: 10}() {
            ok = true;
        } catch {
            ok = false;
        }
        // In reference, pot = 10, then player gets 9, no revert.
        // In buggy, pot stays 0, transfer(pot - 1) = transfer(-1) reverts.
        assertTrue(ok);
    }
}
